window.CODIGO_JAVA = window.CODIGO_JAVA || {};
window.CODIGO_JAVA["facturacion-pagos-ms"] = {"src/main/java/com/mx/josesaid/develop/facturacion_pagos/FacturacionPagosApplication.java": "package com.mx.josesaid.develop.facturacion_pagos;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de facturacion-pagos-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class FacturacionPagosApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(FacturacionPagosApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/api/ComprobanteControlador.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.FacturacionService;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Comprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusCobro;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusComprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Pago;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.DecimalMax;\nimport jakarta.validation.constraints.DecimalMin;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Positive;\nimport jakarta.validation.constraints.Size;\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RestController;\nimport com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia.Idempotencia;\nimport org.springframework.web.bind.annotation.RequestHeader;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.validation.annotation.Validated;\n\n/** Endpoints de comprobantes y pagos. Escribir exige FINANZAS; leer también permite VENTAS. */\n@Validated\n@RestController\n@RequestMapping(\"/v1/comprobantes\")\npublic class ComprobanteControlador {\n\n    private final FacturacionService servicio;\n    private final Idempotencia idempotencia;\n\n    /** Recibe el servicio de facturación y el control de idempotencia. */\n    public ComprobanteControlador(FacturacionService servicio, Idempotencia idempotencia) {\n        this.servicio = servicio;\n        this.idempotencia = idempotencia;\n    }\n\n    /** Crea un comprobante en borrador a partir de una orden. La tasa de IVA la fija el servidor según la fecha. */\n    @PostMapping\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public ComprobanteRespuesta crear(@Valid @RequestBody CrearComprobanteSolicitud solicitud) {\n        return ComprobanteRespuesta.de(servicio.crearBorrador(\n                solicitud.ordenId(), solicitud.moneda(), solicitud.subtotal()));\n    }\n\n    /** Busca un comprobante por su folio. */\n    @GetMapping(params = \"folio\")\n    @PreAuthorize(\"hasAnyRole('FINANZAS','VENTAS')\")\n    public ComprobanteRespuesta buscarPorFolio(@RequestParam @Size(max = 50) String folio) {\n        return ComprobanteRespuesta.de(servicio.buscarPorFolio(folio));\n    }\n\n    /** Últimos 15 comprobantes emitidos con saldo por cobrar, del más reciente al más antiguo. */\n    @GetMapping(\"/pendientes-cobro\")\n    @PreAuthorize(\"hasAnyRole('FINANZAS','VENTAS')\")\n    public List<ComprobantePendienteRespuesta> listarPendientesCobro() {\n        return servicio.listarPendientesDeCobro().stream()\n                .map(c -> new ComprobantePendienteRespuesta(c.id(), c.folio(), c.moneda(), c.total(), c.saldo(),\n                        c.estatusCobro()))\n                .toList();\n    }\n\n    /** Devuelve un comprobante con sus pagos y su saldo. */\n    @GetMapping(\"/{id}\")\n    @PreAuthorize(\"hasAnyRole('FINANZAS','VENTAS')\")\n    public ComprobanteRespuesta obtener(@PathVariable UUID id) {\n        return ComprobanteRespuesta.de(servicio.obtener(id));\n    }\n\n    /** Emite el comprobante y le asigna su folio. */\n    @PostMapping(\"/{id}/emision\")\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public ComprobanteRespuesta emitir(@PathVariable UUID id) {\n        return ComprobanteRespuesta.de(servicio.emitir(id));\n    }\n\n    /** Cancela un comprobante emitido. Requiere motivo. */\n    @PostMapping(\"/{id}/cancelacion\")\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public ComprobanteRespuesta cancelar(@PathVariable UUID id, @Valid @RequestBody CancelarSolicitud solicitud) {\n        return ComprobanteRespuesta.de(servicio.cancelar(id, solicitud.motivo()));\n    }\n\n    /** Registra un pago contra el saldo del comprobante. Acepta Idempotency-Key para reintentar sin duplicar el pago. */\n    @PostMapping(\"/{id}/pagos\")\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public ResponseEntity<?> registrarPago(@RequestHeader(value = Idempotencia.CABECERA, required = false) String clave,\n                                           @PathVariable UUID id,\n                                           @Valid @RequestBody RegistrarPagoSolicitud solicitud) {\n        return idempotencia.ejecutar(clave, \"POST /v1/comprobantes/\" + id + \"/pagos\", solicitud, HttpStatus.CREATED,\n                () -> ComprobanteRespuesta.de(servicio.registrarPago(\n                        id, solicitud.monto(), solicitud.fechaPago(), solicitud.referencia())));\n    }\n\n    /**\n     * Datos para crear el borrador: orden, moneda y subtotal.\n     *\n     * @param ordenId identificador del orden, de tipo {@code UUID}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param subtotal subtotal antes de impuestos, de tipo {@code BigDecimal}.\n     */\n    public record CrearComprobanteSolicitud(\n            @NotNull UUID ordenId,\n            @NotBlank String moneda,\n            @NotNull @Positive BigDecimal subtotal) {\n    }\n\n    /**\n     * Motivo de la cancelación, de hasta 200 caracteres.\n     *\n     * @param motivo motivo del registro o de la acción, de tipo {@code String}.\n     */\n    public record CancelarSolicitud(@NotBlank @Size(max = 200) String motivo) {\n    }\n\n    /**\n     * Datos de un pago: monto, fecha opcional y referencia.\n     *\n     * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n     * @param fechaPago fecha en que se realizó el pago, de tipo {@code LocalDate}.\n     * @param referencia referencia externa o interna del documento, de tipo {@code String}.\n     */\n    public record RegistrarPagoSolicitud(\n            @NotNull @Positive BigDecimal monto,\n            LocalDate fechaPago,\n            @Size(max = 100) String referencia) {\n    }\n\n    /**\n     * Comprobante emitido con saldo pendiente de cobro.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param folio folio, de tipo {@code String}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param total importe total, de tipo {@code BigDecimal}.\n     * @param saldo saldo pendiente, de tipo {@code BigDecimal}.\n     * @param estatusCobro estatus cobro, de tipo {@code EstatusCobro}.\n     */\n    public record ComprobantePendienteRespuesta(UUID id, String folio, String moneda, BigDecimal total,\n                                                BigDecimal saldo, EstatusCobro estatusCobro) {\n    }\n\n    /**\n     * Respuesta de un pago.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n     * @param fechaPago fecha en que se realizó el pago, de tipo {@code LocalDate}.\n     * @param referencia referencia externa o interna del documento, de tipo {@code String}.\n     */\n    public record PagoRespuesta(UUID id, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        /** Convierte un pago en su respuesta. */\n        static PagoRespuesta de(Pago p) {\n            return new PagoRespuesta(p.getId(), p.getMonto(), p.getFechaPago(), p.getReferencia());\n        }\n    }\n\n    /**\n     * Respuesta de un comprobante, con sus pagos y su saldo.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param ordenId identificador del orden, de tipo {@code UUID}.\n     * @param folio folio, de tipo {@code String}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param subtotal subtotal antes de impuestos, de tipo {@code BigDecimal}.\n     * @param iva iva, de tipo {@code BigDecimal}.\n     * @param total importe total, de tipo {@code BigDecimal}.\n     * @param tasaIva tasa de IVA aplicable, de tipo {@code BigDecimal}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusComprobante}.\n     * @param motivoCancelacion motivo cancelacion, de tipo {@code String}.\n     * @param estatusCobro estatus cobro, de tipo {@code EstatusCobro}.\n     * @param pagado pagado, de tipo {@code BigDecimal}.\n     * @param saldo saldo pendiente, de tipo {@code BigDecimal}.\n     * @param pagos pagos, de tipo {@code List<PagoRespuesta>}.\n     */\n    public record ComprobanteRespuesta(\n            UUID id,\n            UUID ordenId,\n            String folio,\n            String moneda,\n            BigDecimal subtotal,\n            BigDecimal iva,\n            BigDecimal total,\n            BigDecimal tasaIva,\n            EstatusComprobante estatus,\n            String motivoCancelacion,\n            EstatusCobro estatusCobro,\n            BigDecimal pagado,\n            BigDecimal saldo,\n            List<PagoRespuesta> pagos) {\n\n        /** Convierte un comprobante en su respuesta. */\n        static ComprobanteRespuesta de(Comprobante c) {\n            return new ComprobanteRespuesta(c.getId(), c.getOrdenId(), c.getFolio(), c.getMoneda(),\n                    c.getSubtotal(), c.getIva(), c.getTotal(), c.getTasaIva(), c.getEstatus(),\n                    c.getMotivoCancelacion(), c.estatusCobro(), c.pagado(), c.saldo(),\n                    c.getPagos().stream().map(PagoRespuesta::de).toList());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/api/CuentasPorPagarControlador.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.CuentasPorPagarService;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagar;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoProveedor;\nimport com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia.Idempotencia;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Positive;\nimport jakarta.validation.constraints.Size;\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestHeader;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Pagos a proveedores. Solo FINANZAS lee y registra. */\n@RestController\n@RequestMapping(\"/v1/cuentas-por-pagar\")\npublic class CuentasPorPagarControlador {\n\n    private final CuentasPorPagarService servicio;\n    private final Idempotencia idempotencia;\n\n    /** Recibe el servicio de cuentas por pagar y el control de idempotencia. */\n    public CuentasPorPagarControlador(CuentasPorPagarService servicio, Idempotencia idempotencia) {\n        this.servicio = servicio;\n        this.idempotencia = idempotencia;\n    }\n\n    /** Últimos 15 pagos a proveedores, del más reciente al más antiguo. */\n    @GetMapping(\"/pagos\")\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public List<PagoListadoRespuesta> listarPagos() {\n        return servicio.listarPagosRecientes().stream()\n                .map(p -> new PagoListadoRespuesta(p.id(), p.cuentaId(), p.monto(), p.fechaPago(), p.referencia()))\n                .toList();\n    }\n\n    /** Devuelve una cuenta por pagar con sus pagos. */\n    @GetMapping(\"/{id}\")\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public CuentaRespuesta obtener(@PathVariable UUID id) {\n        return CuentaRespuesta.de(servicio.obtener(id));\n    }\n\n    /** Registra un pago a proveedor contra el saldo de la cuenta. Acepta Idempotency-Key. */\n    @PostMapping(\"/{id}/pagos\")\n    @PreAuthorize(\"hasRole('FINANZAS')\")\n    public ResponseEntity<?> registrarPago(@RequestHeader(value = Idempotencia.CABECERA, required = false) String clave,\n                                           @PathVariable UUID id,\n                                           @Valid @RequestBody RegistrarPagoSolicitud solicitud) {\n        return idempotencia.ejecutar(clave, \"POST /v1/cuentas-por-pagar/\" + id + \"/pagos\", solicitud,\n                HttpStatus.CREATED,\n                () -> CuentaRespuesta.de(servicio.registrarPago(\n                        id, solicitud.monto(), solicitud.fechaPago(), solicitud.referencia())));\n    }\n\n    /**\n     * Datos de un pago a proveedor: monto, fecha opcional y referencia.\n     *\n     * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n     * @param fechaPago fecha en que se realizó el pago, de tipo {@code LocalDate}.\n     * @param referencia referencia externa o interna del documento, de tipo {@code String}.\n     */\n    public record RegistrarPagoSolicitud(\n            @NotNull @Positive BigDecimal monto,\n            LocalDate fechaPago,\n            @Size(max = 100) String referencia) {\n    }\n\n    /**\n     * Respuesta de una cuenta por pagar.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param ordenId identificador del orden, de tipo {@code UUID}.\n     * @param proveedorId identificador del proveedor, de tipo {@code UUID}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n     * @param saldo saldo pendiente, de tipo {@code BigDecimal}.\n     * @param estatus estado actual del registro, de tipo {@code String}.\n     * @param pagos pagos, de tipo {@code List<PagoRespuesta>}.\n     */\n    public record CuentaRespuesta(UUID id, UUID ordenId, UUID proveedorId, String moneda, BigDecimal monto,\n                                  BigDecimal saldo, String estatus, List<PagoRespuesta> pagos) {\n\n        /** Convierte una cuenta en su respuesta. */\n        static CuentaRespuesta de(CuentaPorPagar c) {\n            return new CuentaRespuesta(c.getId(), c.getOrdenId(), c.getProveedorId(), c.getMoneda(), c.getMonto(),\n                    c.saldo(), c.estatus().name(), c.getPagos().stream().map(PagoRespuesta::de).toList());\n        }\n    }\n\n    /**\n     * Pago dentro de un listado, con la cuenta a la que pertenece.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param cuentaId identificador de la cuenta contable, de tipo {@code UUID}.\n     * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n     * @param fechaPago fecha en que se realizó el pago, de tipo {@code LocalDate}.\n     * @param referencia referencia externa o interna del documento, de tipo {@code String}.\n     */\n    public record PagoListadoRespuesta(UUID id, UUID cuentaId, BigDecimal monto, LocalDate fechaPago,\n                                       String referencia) {\n    }\n\n    /**\n     * Respuesta de un pago a proveedor.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n     * @param fechaPago fecha en que se realizó el pago, de tipo {@code LocalDate}.\n     * @param referencia referencia externa o interna del documento, de tipo {@code String}.\n     */\n    public record PagoRespuesta(UUID id, BigDecimal monto, LocalDate fechaPago, String referencia) {\n\n        /** Convierte un pago a proveedor en su respuesta. */\n        static PagoRespuesta de(PagoProveedor p) {\n            return new PagoRespuesta(p.getId(), p.getMonto(), p.getFechaPago(), p.getReferencia());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/api/ManejadorErrores.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ConflictoException;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ReglaDeNegocioException;\nimport java.net.URI;\nimport java.util.stream.Collectors;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/**\n * Traduce excepciones a respuestas RFC 9457 (ProblemDetail).\n * El {@code type} es estable y usa el prefijo {@code urn:josesaid:facturacion-pagos:error:}.\n */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    private static final String PREFIJO = \"urn:josesaid:facturacion-pagos:error:\";\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ProblemDetail noEncontrado(RecursoNoEncontradoException ex) {\n        return problema(HttpStatus.NOT_FOUND, \"no-encontrado\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de estado en un problema HTTP. */\n    @ExceptionHandler(ConflictoException.class)\n    ProblemDetail conflicto(ConflictoException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto\", ex.getMessage());\n    }\n\n    /** Convierte una regla de negocio incumplida en un problema HTTP, por ejemplo un pago que excede el saldo. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ProblemDetail reglaDeNegocio(ReglaDeNegocioException ex) {\n        return problema(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", ex.getMessage());\n    }\n\n    /** Convierte errores de validación en un problema HTTP con el detalle de cada campo. */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail validacion(MethodArgumentNotValidException ex) {\n        String detalle = ex.getBindingResult().getFieldErrors().stream()\n                .map(e -> e.getField() + \": \" + e.getDefaultMessage())\n                .collect(Collectors.joining(\"; \"));\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", detalle);\n    }\n\n    /** Construye la respuesta de error con su estatus, código y detalle. */\n    private static ProblemDetail problema(HttpStatus estatus, String slug, String detalle) {\n        ProblemDetail pd = ProblemDetail.forStatusAndDetail(estatus, detalle);\n        pd.setType(URI.create(PREFIJO + slug));\n        pd.setTitle(estatus.getReasonPhrase());\n        return pd;\n    }\n\n    /** Convierte parámetros inválidos en un problema HTTP. */\n    @org.springframework.web.bind.annotation.ExceptionHandler(jakarta.validation.ConstraintViolationException.class)\n    org.springframework.http.ProblemDetail parametrosInvalidos(jakarta.validation.ConstraintViolationException e) {\n        return org.springframework.http.ProblemDetail.forStatusAndDetail(\n                org.springframework.http.HttpStatus.BAD_REQUEST, \"Revise los parámetros indicados\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/application/CuentasPorPagarService.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagar;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagarRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoProveedor;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoResumen;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.RecursoNoEncontradoException;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Cuentas por pagar a proveedores. Se alimentan de las órdenes aprobadas en compras-proveedores-ms. */\n@Service\npublic class CuentasPorPagarService {\n\n    public static final String EVENTO_PAGO_PROVEEDOR_REGISTRADO = \"pago-proveedor-registrado\";\n    static final int LIMITE_LISTADO_PAGOS = 15;\n\n    private final CuentaPorPagarRepositorio cuentas;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n\n    /** Recibe el repositorio de cuentas, el publicador de eventos y el reloj. */\n    public CuentasPorPagarService(CuentaPorPagarRepositorio cuentas, PublicadorEventos eventos, Clock reloj) {\n        this.cuentas = cuentas;\n        this.eventos = eventos;\n        this.reloj = reloj;\n    }\n\n    /** Crea la cuenta de una orden aprobada. Si ya existe para esa orden, no hace nada: el evento puede llegar dos veces. */\n    @Transactional\n    public void registrarCuenta(UUID ordenId, UUID proveedorId, String moneda, BigDecimal total) {\n        if (cuentas.buscarPorOrdenId(ordenId).isPresent()) {\n            return;\n        }\n        cuentas.guardar(CuentaPorPagar.crear(ordenId, proveedorId, moneda, total));\n    }\n\n    /** Registra un pago contra el saldo de la cuenta. Si no trae fecha, usa la fecha de hoy. */\n    @Transactional\n    public CuentaPorPagar registrarPago(UUID cuentaId, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        CuentaPorPagar cuenta = obtener(cuentaId);\n        LocalDate fecha = fechaPago != null ? fechaPago : LocalDate.now(reloj);\n        PagoProveedor pago = cuenta.registrarPago(monto, fecha, referencia);\n        CuentaPorPagar guardada = cuentas.guardar(cuenta);\n        eventos.publicar(new EventoDominio(EVENTO_PAGO_PROVEEDOR_REGISTRADO, cuentaId.toString(), Map.of(\n                \"cuentaId\", cuentaId.toString(),\n                \"ordenId\", guardada.getOrdenId().toString(),\n                \"proveedorId\", guardada.getProveedorId().toString(),\n                \"moneda\", guardada.getMoneda(),\n                \"monto\", pago.getMonto().toPlainString(),\n                \"saldo\", guardada.saldo().toPlainString())));\n        return guardada;\n    }\n\n    /** Últimos pagos registrados, para el listado de finanzas y el asistente. */\n    @Transactional(readOnly = true)\n    public List<PagoResumen> listarPagosRecientes() {\n        return cuentas.listarPagosRecientes(LIMITE_LISTADO_PAGOS);\n    }\n\n    /** Devuelve una cuenta por id o lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public CuentaPorPagar obtener(UUID id) {\n        return cuentas.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Cuenta por pagar no encontrada: \" + id));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/application/EventoDominio.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/application/FacturacionService.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Comprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobanteRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobantePendienteCobro;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.RecursoNoEncontradoException;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Casos de uso de facturación. Cada cambio de estado publica un evento en el outbox\n * dentro de la misma transacción.\n */\n@Service\npublic class FacturacionService {\n\n    public static final String EVENTO_COMPROBANTE_EMITIDO = \"comprobante-emitido\";\n    public static final String EVENTO_COMPROBANTE_CANCELADO = \"comprobante-cancelado\";\n    public static final String EVENTO_PAGO_REGISTRADO = \"pago-registrado\";\n\n    static final int LIMITE_LISTADO_PENDIENTES = 15;\n\n    private final ComprobanteRepositorio repositorio;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n\n    /** Recibe el repositorio de comprobantes, el publicador de eventos y el reloj. */\n    public FacturacionService(ComprobanteRepositorio repositorio, PublicadorEventos eventos, Clock reloj) {\n        this.repositorio = repositorio;\n        this.eventos = eventos;\n        this.reloj = reloj;\n    }\n\n    /** Crea un comprobante en borrador para una orden. La fecha de hoy determina la tasa de IVA. */\n    @Transactional\n    public Comprobante crearBorrador(UUID ordenId, String moneda, BigDecimal subtotal) {\n        return repositorio.guardar(Comprobante.crearBorrador(ordenId, moneda, subtotal, LocalDate.now(reloj)));\n    }\n\n    /** Emite el comprobante, le asigna su folio y publica el evento de emisión. */\n    @Transactional\n    public Comprobante emitir(UUID id) {\n        Comprobante comprobante = obtener(id);\n        comprobante.emitir();\n        Comprobante guardado = repositorio.guardar(comprobante);\n        eventos.publicar(new EventoDominio(EVENTO_COMPROBANTE_EMITIDO, id.toString(), Map.of(\n                \"comprobanteId\", id.toString(),\n                \"folio\", guardado.getFolio(),\n                \"total\", guardado.getTotal().toPlainString())));\n        return guardado;\n    }\n\n    /** Cancela un comprobante emitido con motivo y publica el evento de cancelación. */\n    @Transactional\n    public Comprobante cancelar(UUID id, String motivo) {\n        Comprobante comprobante = obtener(id);\n        comprobante.cancelar(motivo);\n        Comprobante guardado = repositorio.guardar(comprobante);\n        eventos.publicar(new EventoDominio(EVENTO_COMPROBANTE_CANCELADO, id.toString(), Map.of(\n                \"comprobanteId\", id.toString(),\n                \"motivo\", guardado.getMotivoCancelacion())));\n        return guardado;\n    }\n\n    /** Registra un pago. Si no trae fecha, se usa la fecha actual del servidor. */\n    @Transactional\n    public Comprobante registrarPago(UUID id, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        Comprobante comprobante = obtener(id);\n        LocalDate fecha = fechaPago != null ? fechaPago : LocalDate.now(reloj);\n        var pago = comprobante.registrarPago(monto, fecha, referencia);\n        Comprobante guardado = repositorio.guardar(comprobante);\n        eventos.publicar(new EventoDominio(EVENTO_PAGO_REGISTRADO, id.toString(), Map.of(\n                \"comprobanteId\", id.toString(),\n                \"monto\", pago.getMonto().toPlainString(),\n                \"saldo\", guardado.saldo().toPlainString())));\n        return guardado;\n    }\n\n    /** Comprobantes emitidos con saldo por cobrar, para cobranza. */\n    @Transactional(readOnly = true)\n    public List<ComprobantePendienteCobro> listarPendientesDeCobro() {\n        return repositorio.listarPendientesDeCobro(LIMITE_LISTADO_PENDIENTES);\n    }\n\n    /** Busca un comprobante por folio o lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public Comprobante buscarPorFolio(String folio) {\n        return repositorio.buscarPorFolio(folio.trim())\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Comprobante no encontrado con folio: \" + folio));\n    }\n\n    /** Devuelve un comprobante por id o lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public Comprobante obtener(UUID id) {\n        return repositorio.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Comprobante no encontrado: \" + id));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/application/PublicadorEventos.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\n/** Puerto de publicación de eventos. La implementación usa el patrón outbox. */\npublic interface PublicadorEventos {\n\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.facturacion_pagos.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code facturacion.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"facturacion.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/config/RelojConfig.java": "package com.mx.josesaid.develop.facturacion_pagos.config;\n\nimport java.time.Clock;\nimport java.time.ZoneId;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC, usado para las fechas de facturación. */\n    @Bean\n    Clock reloj() {\n        return Clock.system(ZoneId.of(\"America/Mexico_City\"));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/config/SeguridadConfig.java": "package com.mx.josesaid.develop.facturacion_pagos.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.facturacion_pagos.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.facturacion_pagos.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.facturacion_pagos.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad de la API sin estado. Exige JWT válido en todo, excepto salud, info y métricas. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/Comprobante.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport static java.math.BigDecimal.ZERO;\nimport static java.math.RoundingMode.HALF_EVEN;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\n\n/**\n * Agregado raíz de facturación.\n *\n * <p>Reglas: un comprobante emitido no se modifica; un pago no excede el saldo; solo se cancela\n * un comprobante emitido y la cancelación exige motivo. No depende de Spring, JPA ni Kafka.\n *\n * <p>El folio es provisional. El timbrado con el PAC y el folio fiscal quedan pendientes.\n */\npublic class Comprobante {\n\n    /** Monedas aceptadas (ISO 4217). Agregar una moneda es configuración del área. */\n    public static final Set<String> MONEDAS = Set.of(\"MXN\", \"USD\");\n\n    private final UUID id;\n    private final UUID ordenId;\n    private final String moneda;\n    private final BigDecimal subtotal;\n    private final BigDecimal iva;\n    private final BigDecimal total;\n    private final BigDecimal tasaIva;\n    private String folio;\n    private EstatusComprobante estatus;\n    private String motivoCancelacion;\n    private final List<Pago> pagos;\n\n    /** Constructor privado: los comprobantes se crean con sus fábricas. */\n    private Comprobante(UUID id, UUID ordenId, String moneda, BigDecimal subtotal, BigDecimal iva,\n                        BigDecimal total, BigDecimal tasaIva, String folio, EstatusComprobante estatus,\n                        String motivoCancelacion, List<Pago> pagos) {\n        this.id = id;\n        this.ordenId = ordenId;\n        this.moneda = moneda;\n        this.subtotal = subtotal;\n        this.iva = iva;\n        this.total = total;\n        this.tasaIva = tasaIva;\n        this.folio = folio;\n        this.estatus = estatus;\n        this.motivoCancelacion = motivoCancelacion;\n        this.pagos = new ArrayList<>(pagos);\n    }\n\n    /** Crea un comprobante en borrador. El IVA y el total se calculan con redondeo bancario. */\n    public static Comprobante crearBorrador(UUID ordenId, String moneda, BigDecimal subtotal, LocalDate fecha) {\n        if (ordenId == null) {\n            throw new ReglaDeNegocioException(\"La orden es obligatoria\");\n        }\n        if (moneda == null || !MONEDAS.contains(moneda)) {\n            throw new ReglaDeNegocioException(\"La moneda no está permitida: \" + moneda);\n        }\n        if (subtotal == null || subtotal.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"El subtotal debe ser mayor a cero\");\n        }\n        if (fecha == null) {\n            throw new ReglaDeNegocioException(\"La fecha es obligatoria\");\n        }\n        BigDecimal tasaIva = TasaIva.paraFecha(fecha);\n        BigDecimal subtotalRedondeado = subtotal.setScale(2, HALF_EVEN);\n        BigDecimal ivaCalculado = subtotalRedondeado.multiply(tasaIva).setScale(2, HALF_EVEN);\n        BigDecimal totalCalculado = subtotalRedondeado.add(ivaCalculado);\n        return new Comprobante(UUID.randomUUID(), ordenId, moneda, subtotalRedondeado, ivaCalculado,\n                totalCalculado, tasaIva, null, EstatusComprobante.BORRADOR, null, List.of());\n    }\n\n    /** Reconstruye desde la persistencia sin volver a validar. */\n    public static Comprobante reconstruir(UUID id, UUID ordenId, String moneda, BigDecimal subtotal,\n                                          BigDecimal iva, BigDecimal total, BigDecimal tasaIva, String folio,\n                                          EstatusComprobante estatus, String motivoCancelacion, List<Pago> pagos) {\n        return new Comprobante(id, ordenId, moneda, subtotal, iva, total, tasaIva, folio, estatus,\n                motivoCancelacion, pagos);\n    }\n\n    /** Emite el comprobante y asigna el folio. Solo desde BORRADOR. */\n    public void emitir() {\n        if (estatus != EstatusComprobante.BORRADOR) {\n            throw new ReglaDeNegocioException(\"Solo un comprobante en borrador puede emitirse\");\n        }\n        this.folio = generarFolioProvisional();\n        this.estatus = EstatusComprobante.EMITIDO;\n    }\n\n    /** Cancela un comprobante emitido. El motivo es obligatorio. El registro no se borra. */\n    public void cancelar(String motivo) {\n        if (motivo == null || motivo.isBlank()) {\n            throw new ReglaDeNegocioException(\"El motivo de cancelación es obligatorio\");\n        }\n        if (estatus != EstatusComprobante.EMITIDO) {\n            throw new ReglaDeNegocioException(\"Solo un comprobante emitido puede cancelarse\");\n        }\n        this.estatus = EstatusComprobante.CANCELADO;\n        this.motivoCancelacion = motivo.trim();\n    }\n\n    /**\n     * Registra un pago contra el saldo pendiente. Solo en comprobantes emitidos.\n     * Si la fecha es nula, la capa de aplicación la asigna.\n     */\n    public Pago registrarPago(BigDecimal monto, LocalDate fechaPago, String referencia) {\n        if (estatus != EstatusComprobante.EMITIDO) {\n            throw new ReglaDeNegocioException(\"Solo se pueden registrar pagos en comprobantes emitidos\");\n        }\n        if (monto == null || monto.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"El monto del pago debe ser mayor a cero\");\n        }\n        if (fechaPago == null) {\n            throw new ReglaDeNegocioException(\"La fecha del pago es obligatoria\");\n        }\n        BigDecimal montoRedondeado = monto.setScale(2, HALF_EVEN);\n        if (montoRedondeado.compareTo(saldo()) > 0) {\n            throw new ReglaDeNegocioException(\"El pago excede el saldo pendiente\");\n        }\n        Pago pago = new Pago(UUID.randomUUID(), montoRedondeado, fechaPago, referencia);\n        pagos.add(pago);\n        return pago;\n    }\n\n    /** Devuelve la suma de los pagos registrados. */\n    public BigDecimal pagado() {\n        return pagos.stream().map(Pago::getMonto).reduce(ZERO, BigDecimal::add);\n    }\n\n    /** Devuelve el saldo pendiente. Nunca es negativo. */\n    public BigDecimal saldo() {\n        BigDecimal saldo = total.subtract(pagado());\n        return saldo.signum() < 0 ? ZERO : saldo;\n    }\n\n    /** Devuelve el estado de cobro: pendiente, parcial o pagado. */\n    public EstatusCobro estatusCobro() {\n        if (pagado().signum() == 0) {\n            return EstatusCobro.PENDIENTE;\n        }\n        return saldo().signum() == 0 ? EstatusCobro.PAGADO : EstatusCobro.PARCIAL;\n    }\n\n    /** Folio provisional de 8 caracteres. Se reemplazará por el folio fiscal del PAC. */\n    private static String generarFolioProvisional() {\n        return \"FAC-\" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id de la orden. */\n    public UUID getOrdenId() { return ordenId; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve el subtotal. */\n    public BigDecimal getSubtotal() { return subtotal; }\n    /** Devuelve el IVA. */\n    public BigDecimal getIva() { return iva; }\n    /** Devuelve el total. */\n    public BigDecimal getTotal() { return total; }\n    /** Devuelve la tasa de IVA aplicada al crearlo. */\n    public BigDecimal getTasaIva() { return tasaIva; }\n    /** Devuelve el folio, o nulo si aún es borrador. */\n    public String getFolio() { return folio; }\n    /** Devuelve el estatus. */\n    public EstatusComprobante getEstatus() { return estatus; }\n    /** Devuelve el motivo de cancelación, o nulo. */\n    public String getMotivoCancelacion() { return motivoCancelacion; }\n\n    /** Vista de solo lectura de los pagos. */\n    public List<Pago> getPagos() {\n        return Collections.unmodifiableList(pagos);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/ComprobantePendienteCobro.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/**\n * Comprobante emitido con saldo por cobrar, para el listado de cobranza.\n *\n * @param id identificador único del registro, de tipo {@code UUID}.\n * @param folio folio, de tipo {@code String}.\n * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n * @param total importe total, de tipo {@code BigDecimal}.\n * @param saldo saldo pendiente, de tipo {@code BigDecimal}.\n * @param estatusCobro estatus cobro, de tipo {@code EstatusCobro}.\n */\npublic record ComprobantePendienteCobro(UUID id, String folio, String moneda, BigDecimal total, BigDecimal saldo,\n                                        EstatusCobro estatusCobro) {\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/ComprobanteRepositorio.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto de persistencia del agregado Comprobante. La implementación vive en infraestructura. */\npublic interface ComprobanteRepositorio {\n\n    Comprobante guardar(Comprobante comprobante);\n\n    Optional<Comprobante> buscarPorId(UUID id);\n\n    Optional<Comprobante> buscarPorFolio(String folio);\n\n    /** Emitidos con saldo pendiente, del más reciente al más antiguo, hasta {@code limite}. */\n    List<ComprobantePendienteCobro> listarPendientesDeCobro(int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/ConflictoException.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\n/** Conflicto con el estado actual del recurso. Se traduce a HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Se lanza cuando la operación choca con el estado actual. Se responde como conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/CuentaPorPagar.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport static java.math.BigDecimal.ZERO;\n\nimport java.math.BigDecimal;\nimport java.math.RoundingMode;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\n\n/**\n * Cuenta por pagar a un proveedor: se crea al aprobarse una orden de compra y recibe pagos hasta saldarla.\n * Un pago no puede exceder el saldo.\n */\npublic class CuentaPorPagar {\n\n    private static final Set<String> MONEDAS = Set.of(\"MXN\", \"USD\");\n\n    private final UUID id;\n    private final UUID ordenId;\n    private final UUID proveedorId;\n    private final String moneda;\n    private final BigDecimal monto;\n    private final List<PagoProveedor> pagos;\n\n    /** Constructor privado: las cuentas se crean con sus fábricas. */\n    private CuentaPorPagar(UUID id, UUID ordenId, UUID proveedorId, String moneda, BigDecimal monto,\n                           List<PagoProveedor> pagos) {\n        this.id = id;\n        this.ordenId = ordenId;\n        this.proveedorId = proveedorId;\n        this.moneda = moneda;\n        this.monto = monto;\n        this.pagos = new ArrayList<>(pagos);\n    }\n\n    /** Crea una cuenta por pagar en MXN o USD. Requiere orden, proveedor y monto mayor a cero. */\n    public static CuentaPorPagar crear(UUID ordenId, UUID proveedorId, String moneda, BigDecimal monto) {\n        if (ordenId == null) {\n            throw new ReglaDeNegocioException(\"La cuenta por pagar necesita la orden\");\n        }\n        if (proveedorId == null) {\n            throw new ReglaDeNegocioException(\"La cuenta por pagar necesita el proveedor\");\n        }\n        if (moneda == null || !MONEDAS.contains(moneda)) {\n            throw new ReglaDeNegocioException(\"La moneda no está permitida: \" + moneda);\n        }\n        if (monto == null || monto.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"El monto de la cuenta debe ser mayor a cero\");\n        }\n        return new CuentaPorPagar(UUID.randomUUID(), ordenId, proveedorId, moneda,\n                monto.setScale(2, RoundingMode.HALF_EVEN), List.of());\n    }\n\n    /** Reconstruye la cuenta desde la base de datos sin volver a validar. */\n    public static CuentaPorPagar reconstruir(UUID id, UUID ordenId, UUID proveedorId, String moneda,\n                                             BigDecimal monto, List<PagoProveedor> pagos) {\n        return new CuentaPorPagar(id, ordenId, proveedorId, moneda, monto, pagos);\n    }\n\n    /** Registra un pago contra el saldo pendiente. Un monto que redondea a cero o excede el saldo se rechaza. */\n    public PagoProveedor registrarPago(BigDecimal montoPago, LocalDate fechaPago, String referencia) {\n        if (montoPago == null) {\n            throw new ReglaDeNegocioException(\"El monto del pago debe ser mayor a cero\");\n        }\n        BigDecimal redondeado = montoPago.setScale(2, RoundingMode.HALF_EVEN);\n        if (redondeado.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"El monto del pago debe ser mayor a cero\");\n        }\n        if (fechaPago == null) {\n            throw new ReglaDeNegocioException(\"La fecha del pago es obligatoria\");\n        }\n        if (redondeado.compareTo(saldo()) > 0) {\n            throw new ReglaDeNegocioException(\"El pago excede el saldo pendiente\");\n        }\n        PagoProveedor pago = new PagoProveedor(UUID.randomUUID(), redondeado, fechaPago, referencia);\n        pagos.add(pago);\n        return pago;\n    }\n\n    /** Devuelve la suma de los pagos registrados. */\n    public BigDecimal pagado() {\n        return pagos.stream().map(PagoProveedor::getMonto).reduce(ZERO, BigDecimal::add);\n    }\n\n    /** Devuelve el saldo pendiente. Nunca es negativo. */\n    public BigDecimal saldo() {\n        BigDecimal saldo = monto.subtract(pagado());\n        return saldo.signum() < 0 ? ZERO : saldo;\n    }\n\n    /** Devuelve PENDIENTE, PARCIAL o PAGADA según los pagos registrados. */\n    public EstatusCuentaPorPagar estatus() {\n        if (pagos.isEmpty()) {\n            return EstatusCuentaPorPagar.PENDIENTE;\n        }\n        return saldo().signum() == 0 ? EstatusCuentaPorPagar.PAGADA : EstatusCuentaPorPagar.PARCIAL;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id de la orden de compra. */\n    public UUID getOrdenId() { return ordenId; }\n    /** Devuelve el id del proveedor. */\n    public UUID getProveedorId() { return proveedorId; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve el monto total de la cuenta. */\n    public BigDecimal getMonto() { return monto; }\n\n    /** Vista de solo lectura de los pagos. */\n    public List<PagoProveedor> getPagos() {\n        return Collections.unmodifiableList(pagos);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/CuentaPorPagarRepositorio.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto de persistencia de cuentas por pagar. La implementación vive en infraestructura. */\npublic interface CuentaPorPagarRepositorio {\n\n    CuentaPorPagar guardar(CuentaPorPagar cuenta);\n\n    Optional<CuentaPorPagar> buscarPorId(UUID id);\n\n    Optional<CuentaPorPagar> buscarPorOrdenId(UUID ordenId);\n\n    /** Pagos más recientes primero, por fecha de pago y luego por registro. */\n    List<PagoResumen> listarPagosRecientes(int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/EstatusCobro.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\n/** Estado de cobro, derivado de los pagos registrados. */\npublic enum EstatusCobro {\n    PENDIENTE,\n    PARCIAL,\n    PAGADO\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/EstatusComprobante.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\n/** Ciclo de vida del comprobante: BORRADOR → EMITIDO → CANCELADO. */\npublic enum EstatusComprobante {\n    BORRADOR,\n    EMITIDO,\n    CANCELADO\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/EstatusCuentaPorPagar.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\n/** PENDIENTE sin pagos; PARCIAL con pagos y saldo; PAGADA con saldo en cero. */\npublic enum EstatusCuentaPorPagar { PENDIENTE, PARCIAL, PAGADA }\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/Pago.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Pago aplicado a un comprobante. Es inmutable: no se modifica ni se borra. */\npublic final class Pago {\n\n    private final UUID id;\n    private final BigDecimal monto;\n    private final LocalDate fechaPago;\n    private final String referencia;\n\n    /** Crea un pago registrado contra un comprobante. */\n    public Pago(UUID id, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        this.id = id;\n        this.monto = monto;\n        this.fechaPago = fechaPago;\n        this.referencia = referencia;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el monto. */\n    public BigDecimal getMonto() { return monto; }\n    /** Devuelve la fecha del pago. */\n    public LocalDate getFechaPago() { return fechaPago; }\n    /** Devuelve la referencia del pago. */\n    public String getReferencia() { return referencia; }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/PagoProveedor.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Pago registrado contra una cuenta por pagar. Es inmutable: no se modifica ni se borra. */\npublic final class PagoProveedor {\n\n    private final UUID id;\n    private final BigDecimal monto;\n    private final LocalDate fechaPago;\n    private final String referencia;\n\n    /** Crea un pago a proveedor registrado contra una cuenta por pagar. */\n    public PagoProveedor(UUID id, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        this.id = id;\n        this.monto = monto;\n        this.fechaPago = fechaPago;\n        this.referencia = referencia;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el monto. */\n    public BigDecimal getMonto() { return monto; }\n    /** Devuelve la fecha del pago. */\n    public LocalDate getFechaPago() { return fechaPago; }\n    /** Devuelve la referencia del pago. */\n    public String getReferencia() { return referencia; }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/PagoResumen.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/**\n * Pago a proveedor visto desde el listado: sin el detalle de la cuenta.\n *\n * @param id identificador único del registro, de tipo {@code UUID}.\n * @param cuentaId identificador de la cuenta contable, de tipo {@code UUID}.\n * @param monto monto del movimiento, de tipo {@code BigDecimal}.\n * @param fechaPago fecha en que se realizó el pago, de tipo {@code LocalDate}.\n * @param referencia referencia externa o interna del documento, de tipo {@code String}.\n */\npublic record PagoResumen(UUID id, UUID cuentaId, BigDecimal monto, LocalDate fechaPago, String referencia) {\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\n/** El recurso no existe. Se traduce a HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Se lanza cuando no existe el recurso pedido. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\n/** Una operación viola una regla de negocio. Se traduce a HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al cliente. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/domain/TasaIva.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\n\n/**\n * Tasa de IVA según la fecha de emisión. Desde el 1 de noviembre de 2026 aplica la tasa fronteriza\n * del 8 % a todas las operaciones; antes, la tasa general del 16 %. La fija el servidor: el cliente\n * no la envía.\n */\npublic final class TasaIva {\n\n    public static final LocalDate INICIO_FRONTERIZO = LocalDate.of(2026, 11, 1);\n    static final BigDecimal GENERAL = new BigDecimal(\"0.16\");\n    static final BigDecimal FRONTERIZO = new BigDecimal(\"0.08\");\n\n    /** Clase de utilidad; no se instancia. */\n    private TasaIva() {\n    }\n\n    /** Devuelve la tasa de IVA vigente para la fecha: 16 % antes del 1 de noviembre de 2026 y 8 % desde esa fecha. */\n    public static BigDecimal paraFecha(LocalDate fecha) {\n        return fecha.isBefore(INICIO_FRONTERIZO) ? GENERAL : FRONTERIZO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/compras/ListenerOrdenesCompra.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.compras;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.CuentasPorPagarService;\nimport java.math.BigDecimal;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Crea una cuenta por pagar por cada orden aprobada en compras-proveedores-ms.\n * Un mensaje mal formado o con datos inválidos se registra y se descarta. Un fallo de base de datos se propaga\n * para que Kafka reintente.\n */\n@Component\npublic class ListenerOrdenesCompra {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerOrdenesCompra.class);\n    static final String TIPO_ORDEN_APROBADA = \"orden-compra-aprobada\";\n\n    private final CuentasPorPagarService servicio;\n    private final ObjectMapper mapper;\n\n    /** Recibe el servicio de cuentas por pagar y el lector JSON. */\n    public ListenerOrdenesCompra(CuentasPorPagarService servicio, ObjectMapper mapper) {\n        this.servicio = servicio;\n        this.mapper = mapper;\n    }\n\n    /** Recibe desde Kafka la orden de compra aprobada y crea su cuenta por pagar. */\n    @KafkaListener(topics = \"${cuentas.topico-compras:compras.eventos}\",\n                   groupId = \"facturacion-pagos-ms-cuentas-por-pagar\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        Datos datos;\n        try {\n            datos = aDatos(mensaje);\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de compras descartado: {}\", e.getClass().getSimpleName());\n            return;\n        }\n        if (datos != null) {\n            servicio.registrarCuenta(datos.ordenId(), datos.proveedorId(), datos.moneda(), datos.total());\n        }\n    }\n\n    /** Devuelve null para eventos ajenos; lanza IllegalArgumentException para datos inválidos. */\n    private Datos aDatos(String mensaje) {\n        Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n        if (!TIPO_ORDEN_APROBADA.equals(sobre.tipo())) {\n            return null;\n        }\n        Map<String, Object> d = sobre.datos();\n        String moneda = String.valueOf(d.get(\"moneda\"));\n        if (!\"MXN\".equals(moneda) && !\"USD\".equals(moneda)) {\n            throw new IllegalArgumentException(\"moneda inválida o ausente en la orden \" + d.get(\"id\"));\n        }\n        BigDecimal total = new BigDecimal(String.valueOf(d.get(\"total\")));\n        if (total.signum() <= 0) {\n            throw new IllegalArgumentException(\"total no positivo en la orden \" + d.get(\"id\"));\n        }\n        return new Datos(UUID.fromString(String.valueOf(d.get(\"id\"))),\n                UUID.fromString(String.valueOf(d.get(\"proveedor_id\"))), moneda, total);\n    }\n\n    /**\n     * Datos extraídos del evento: orden, proveedor, moneda y total.\n     *\n     * @param ordenId identificador del orden, de tipo {@code UUID}.\n     * @param proveedorId identificador del proveedor, de tipo {@code UUID}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param total importe total, de tipo {@code BigDecimal}.\n     */\n    private record Datos(UUID ordenId, UUID proveedorId, String moneda, BigDecimal total) {\n    }\n\n    /**\n     * Sobre que publica compras-proveedores-ms por el outbox.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n     * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n     * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/idempotencia/Idempotencia.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ConflictoException;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ReglaDeNegocioException;\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.util.HexFormat;\nimport java.util.function.Supplier;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.stereotype.Component;\n\n/**\n * Hace seguras de reintentar las altas que reciben la cabecera Idempotency-Key.\n * Misma clave y misma petición: devuelve la respuesta original, sin crear nada nuevo.\n * Misma clave con otra petición: 422. Clave todavía en proceso: 409.\n * Sin cabecera: la operación se ejecuta como siempre.\n */\n@Component\npublic class Idempotencia {\n\n    public static final String CABECERA = \"Idempotency-Key\";\n\n    private final RegistroIdempotencia registro;\n    private final ObjectMapper mapper;\n\n    /** Recibe el registro de claves y el serializador JSON. */\n    public Idempotencia(RegistroIdempotencia registro, ObjectMapper mapper) {\n        this.registro = registro;\n        this.mapper = mapper;\n    }\n\n    /** Ejecuta una operación una sola vez por Idempotency-Key. Una misma clave con la misma petición devuelve la respuesta guardada; con otra petición, rechaza. Si la operación falla, libera la clave para reintentar. */\n    public <T> ResponseEntity<?> ejecutar(String clave, String ruta, Object peticion,\n                                          HttpStatus estado, Supplier<T> operacion) {\n        if (clave == null || clave.isBlank()) {\n            return ResponseEntity.status(estado).body(operacion.get());\n        }\n        String huella = huella(ruta, peticion);\n        if (!registro.reservar(clave, huella)) {\n            RegistroIdempotencia.Registro previo = registro.buscar(clave)\n                    .orElseThrow(() -> new ConflictoException(\"La Idempotency-Key ya no está disponible. Intente de nuevo.\"));\n            if (!previo.huella().equals(huella)) {\n                throw new ReglaDeNegocioException(\"La Idempotency-Key ya se usó con una petición distinta.\");\n            }\n            if (!previo.completada()) {\n                throw new ConflictoException(\"La petición con esta Idempotency-Key aún se está procesando.\");\n            }\n            return ResponseEntity.status(previo.estatus())\n                    .contentType(MediaType.APPLICATION_JSON)\n                    .body(previo.cuerpo());\n        }\n        T cuerpo;\n        try {\n            cuerpo = operacion.get();\n        } catch (RuntimeException e) {\n            registro.liberar(clave);\n            throw e;\n        }\n        registro.completar(clave, estado.value(), serializar(cuerpo));\n        return ResponseEntity.status(estado).body(cuerpo);\n    }\n\n    /** Calcula la huella SHA-256 de la ruta y el cuerpo de la petición, para detectar si una clave se reutiliza con otra petición. */\n    private String huella(String ruta, Object peticion) {\n        try {\n            byte[] digest = MessageDigest.getInstance(\"SHA-256\")\n                    .digest((ruta + \"\\n\" + mapper.writeValueAsString(peticion)).getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest);\n        } catch (JsonProcessingException | NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"No se pudo calcular la huella de la petición\", e);\n        }\n    }\n\n    /** Convierte la respuesta en JSON para guardarla. */\n    private String serializar(Object cuerpo) {\n        try {\n            return mapper.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo guardar la respuesta idempotente\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/idempotencia/RegistroIdempotencia.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia;\n\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DuplicateKeyException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/**\n * Guarda el estado de cada clave Idempotency-Key. Una respuesta completada se conserva 24 horas.\n * Una reserva que nunca se completó (la petición murió a medio camino) se puede retomar tras\n * {@link #CONCESION_RESERVA}, para que la clave no quede bloqueada todo el día.\n */\n@Repository\nclass RegistroIdempotencia {\n\n    static final Duration VIGENCIA = Duration.ofHours(24);\n    static final Duration CONCESION_RESERVA = Duration.ofMinutes(2);\n\n    /**\n     * Fila guardada para una clave: huella, estatus HTTP, cuerpo de la respuesta y si ya terminó.\n     *\n     * @param huella huella, de tipo {@code String}.\n     * @param estatus estado actual del registro, de tipo {@code int}.\n     * @param cuerpo contenido principal del mensaje, de tipo {@code String}.\n     * @param completada completada, de tipo {@code boolean}.\n     */\n    record Registro(String huella, int estatus, String cuerpo, boolean completada) {}\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    RegistroIdempotencia(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Busca el registro de una clave que sigue vigente. */\n    Optional<Registro> buscar(String clave) {\n        return jdbc.query(\n                \"SELECT huella, estatus_http, cuerpo, completada FROM idempotencia WHERE clave = ? AND creado_utc > ?\",\n                (rs, n) -> new Registro(rs.getString(1), rs.getInt(2), rs.getString(3), rs.getBoolean(4)),\n                clave, enTiempo(vencimiento())).stream().findFirst();\n    }\n\n    /**\n     * Reserva la clave. Devuelve false si otra petición la tiene en curso o ya terminó.\n     * Si la reserva existente nunca se completó y su concesión venció, la retoma.\n     */\n    boolean reservar(String clave, String huella) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE creado_utc <= ?\", enTiempo(vencimiento()));\n        try {\n            jdbc.update(\"INSERT INTO idempotencia (clave, huella, estatus_http, cuerpo, completada, creado_utc) VALUES (?, ?, 0, NULL, FALSE, ?)\",\n                    clave, huella, enTiempo(reloj.instant()));\n            return true;\n        } catch (DuplicateKeyException e) {\n            return retomarReservaVencida(clave, huella);\n        }\n    }\n\n    /** Solo una petición gana la retoma: el UPDATE es condicional, así que es atómico. */\n    private boolean retomarReservaVencida(String clave, String huella) {\n        Instant ahora = reloj.instant();\n        int filas = jdbc.update(\n                \"UPDATE idempotencia SET huella = ?, creado_utc = ? WHERE clave = ? AND completada = FALSE AND creado_utc <= ?\",\n                huella, enTiempo(ahora), clave, enTiempo(ahora.minus(CONCESION_RESERVA)));\n        return filas == 1;\n    }\n\n    /** Guarda la respuesta de una operación terminada. */\n    void completar(String clave, int estatus, String cuerpo) {\n        jdbc.update(\"UPDATE idempotencia SET estatus_http = ?, cuerpo = ?, completada = TRUE WHERE clave = ?\",\n                estatus, cuerpo, clave);\n    }\n\n    /** Libera la reserva cuando la operación falló, para que el cliente pueda reintentar. */\n    void liberar(String clave) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE clave = ? AND completada = FALSE\", clave);\n    }\n\n    /** Calcula el límite de vigencia de las claves. */\n    private Instant vencimiento() {\n        return reloj.instant().minus(VIGENCIA);\n    }\n\n    /** Convierte un instante a Timestamp para la base de datos. */\n    private static Timestamp enTiempo(Instant instante) {\n        return Timestamp.from(instante);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/indicadores/PublicadorIndicadoresCobranza.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"cobrado del mes\" del área de finanzas.\n *\n * <p>Cobrado = suma de pagos en MXN de comprobantes EMITIDOS, asignados al mes de su fecha de pago.\n * El comprobante ya incluye IVA. Se recalculan el mes actual y el anterior en cada ciclo. Es una foto\n * del periodo, no un evento: no pasa por el outbox; si un envío falla, el siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresCobranza {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresCobranza.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"FINANZAS_CONTABILIDAD\";\n    public static final String NOMBRE = \"cobrado_mes\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_COBRADO = \"\"\"\n            SELECT COALESCE(SUM(p.monto), 0)\n            FROM pagos p\n            JOIN comprobantes c ON c.id = p.comprobante_id\n            WHERE c.moneda = 'MXN'\n              AND c.estatus = 'EMITIDO'\n              AND TO_CHAR(p.fecha_pago, 'YYYY-MM') = ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para sumar cobros, Kafka para publicar, el serializador, el reloj y el tópico. */\n    public PublicadorIndicadoresCobranza(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                         ObjectMapper mapper, Clock reloj,\n                                         @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica el monto cobrado del mes actual y del anterior. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        YearMonth actual = YearMonth.now(reloj.withZone(ZONA));\n        publicarPeriodo(actual.minusMonths(1).toString());\n        publicarPeriodo(actual.toString());\n    }\n\n    /** Calcula y envía el indicador de un mes (\"AAAA-MM\"). Un fallo se registra y se reintenta en el siguiente ciclo. */\n    public void publicarPeriodo(String periodo) {\n        BigDecimal valor = jdbc.queryForObject(SQL_COBRADO, BigDecimal.class, periodo);\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param periodo periodo de referencia (por ejemplo, año y mes), de tipo {@code String}.\n     * @param valor valor registrado, de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc fecha y hora (UTC) de la última actualización de la fuente, de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.EventoDominio;\nimport com.mx.josesaid.develop.facturacion_pagos.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el serializador JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"facturacion-pagos.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, el evento queda para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${facturacion.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/ComprobanteEntity.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Comprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusComprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Pago;\nimport jakarta.persistence.CascadeType;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.OneToMany;\nimport jakarta.persistence.OrderBy;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\nimport java.util.stream.Collectors;\n\n/** Mapeo JPA del agregado Comprobante. Es un detalle de infraestructura, no de dominio. */\n@Entity\n@Table(name = \"comprobantes\")\npublic class ComprobanteEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"orden_id\", nullable = false)\n    private UUID ordenId;\n\n    @Column(length = 20, unique = true)\n    private String folio;\n\n    @Column(nullable = false, length = 3)\n    private String moneda;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    private BigDecimal subtotal;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    private BigDecimal iva;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    private BigDecimal total;\n\n    @Column(name = \"tasa_iva\", nullable = false, precision = 5, scale = 4)\n    private BigDecimal tasaIva;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 20)\n    private EstatusComprobante estatus;\n\n    @Column(name = \"motivo_cancelacion\", length = 200)\n    private String motivoCancelacion;\n\n    @Version\n    private Long version;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"actualizado_utc\", nullable = false)\n    private Instant actualizadoUtc;\n\n    @OneToMany(mappedBy = \"comprobante\", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)\n    @OrderBy(\"creadoUtc ASC\")\n    private List<PagoEntity> pagos = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected ComprobanteEntity() {\n    }\n\n    ComprobanteEntity(UUID id) {\n        this.id = id;\n        this.creadoUtc = Instant.now();\n    }\n\n    /** Copia el estado del dominio. Los pagos nuevos se agregan; los existentes no cambian. */\n    void actualizarDesde(Comprobante c) {\n        this.ordenId = c.getOrdenId();\n        this.folio = c.getFolio();\n        this.moneda = c.getMoneda();\n        this.subtotal = c.getSubtotal();\n        this.iva = c.getIva();\n        this.total = c.getTotal();\n        this.tasaIva = c.getTasaIva();\n        this.estatus = c.getEstatus();\n        this.motivoCancelacion = c.getMotivoCancelacion();\n        this.actualizadoUtc = Instant.now();\n\n        Set<UUID> existentes = pagos.stream().map(PagoEntity::getId).collect(Collectors.toSet());\n        for (Pago p : c.getPagos()) {\n            if (!existentes.contains(p.getId())) {\n                pagos.add(new PagoEntity(p.getId(), this, p.getMonto(), p.getFechaPago(), p.getReferencia()));\n            }\n        }\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id de la orden. */\n    public UUID getOrdenId() { return ordenId; }\n    /** Devuelve el folio. */\n    public String getFolio() { return folio; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve el subtotal. */\n    public BigDecimal getSubtotal() { return subtotal; }\n    /** Devuelve el IVA. */\n    public BigDecimal getIva() { return iva; }\n    /** Devuelve el total. */\n    public BigDecimal getTotal() { return total; }\n    /** Devuelve la tasa de IVA. */\n    public BigDecimal getTasaIva() { return tasaIva; }\n    /** Devuelve el estatus. */\n    public EstatusComprobante getEstatus() { return estatus; }\n    /** Devuelve el motivo de cancelación. */\n    public String getMotivoCancelacion() { return motivoCancelacion; }\n    /** Devuelve los pagos del comprobante. */\n    public List<PagoEntity> getPagos() { return pagos; }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/ComprobanteJpaRepository.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusComprobante;\n\n/** Acceso a la tabla de comprobantes con Spring Data JPA. */\ninterface ComprobanteJpaRepository extends JpaRepository<ComprobanteEntity, UUID> {\n\n    Optional<ComprobanteEntity> findByFolio(String folio);\n\n    Page<ComprobanteEntity> findByEstatusOrderByCreadoUtcDesc(EstatusComprobante estatus, Pageable pageable);\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/ComprobanteRepositorioJpa.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Comprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobanteRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobantePendienteCobro;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusCobro;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusComprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Pago;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.PageRequest;\nimport org.springframework.stereotype.Component;\n\n/** Adaptador que implementa el puerto de dominio con JPA. */\n@Component\nclass ComprobanteRepositorioJpa implements ComprobanteRepositorio {\n\n    private static final int TAMANO_PAGINA = 50;\n\n    private final ComprobanteJpaRepository jpa;\n\n    ComprobanteRepositorioJpa(ComprobanteJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un comprobante con sus pagos y devuelve el guardado. */\n    @Override\n    public Comprobante guardar(Comprobante comprobante) {\n        ComprobanteEntity entidad = jpa.findById(comprobante.getId())\n                .orElseGet(() -> new ComprobanteEntity(comprobante.getId()));\n        entidad.actualizarDesde(comprobante);\n        return aDominio(jpa.save(entidad));\n    }\n\n    /** Busca un comprobante por id. */\n    @Override\n    public Optional<Comprobante> buscarPorId(UUID id) {\n        return jpa.findById(id).map(this::aDominio);\n    }\n\n    /** El saldo es calculado, así que se filtra en memoria por páginas hasta reunir el límite. */\n    @Override\n    public List<ComprobantePendienteCobro> listarPendientesDeCobro(int limite) {\n        List<ComprobantePendienteCobro> resultado = new ArrayList<>();\n        Page<ComprobanteEntity> pagina;\n        int numero = 0;\n        do {\n            pagina = jpa.findByEstatusOrderByCreadoUtcDesc(EstatusComprobante.EMITIDO,\n                    PageRequest.of(numero++, TAMANO_PAGINA));\n            for (ComprobanteEntity entidad : pagina.getContent()) {\n                Comprobante comprobante = aDominio(entidad);\n                if (comprobante.estatusCobro() != EstatusCobro.PAGADO) {\n                    resultado.add(new ComprobantePendienteCobro(comprobante.getId(), comprobante.getFolio(),\n                            comprobante.getMoneda(), comprobante.getTotal(), comprobante.saldo(),\n                            comprobante.estatusCobro()));\n                    if (resultado.size() == limite) {\n                        return resultado;\n                    }\n                }\n            }\n        } while (pagina.hasNext());\n        return resultado;\n    }\n\n    /** Busca un comprobante por folio. */\n    @Override\n    public Optional<Comprobante> buscarPorFolio(String folio) {\n        return jpa.findByFolio(folio).map(this::aDominio);\n    }\n\n    /** Convierte la fila en el comprobante del dominio. */\n    private Comprobante aDominio(ComprobanteEntity e) {\n        List<Pago> pagos = e.getPagos().stream()\n                .map(p -> new Pago(p.getId(), p.getMonto(), p.getFechaPago(), p.getReferencia()))\n                .toList();\n        return Comprobante.reconstruir(e.getId(), e.getOrdenId(), e.getMoneda(), e.getSubtotal(), e.getIva(),\n                e.getTotal(), e.getTasaIva(), e.getFolio(), e.getEstatus(), e.getMotivoCancelacion(), pagos);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/CuentaPorPagarEntity.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagar;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoProveedor;\nimport jakarta.persistence.CascadeType;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.OneToMany;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Mapeo JPA de la cuenta por pagar. Detalle de infraestructura, no de dominio. */\n@Entity\n@Table(name = \"cuentas_por_pagar\")\npublic class CuentaPorPagarEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"orden_id\", nullable = false, unique = true)\n    private UUID ordenId;\n\n    @Column(name = \"proveedor_id\", nullable = false)\n    private UUID proveedorId;\n\n    @Column(nullable = false, length = 3)\n    private String moneda;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    private BigDecimal monto;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Version\n    private Long version;\n\n    @OneToMany(mappedBy = \"cuenta\", cascade = CascadeType.ALL, orphanRemoval = true)\n    private List<PagoProveedorEntity> pagos = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected CuentaPorPagarEntity() {\n    }\n\n    CuentaPorPagarEntity(UUID id) {\n        this.id = id;\n        this.creadoUtc = Instant.now();\n    }\n\n    /** Actualiza la fila con los datos de la cuenta. */\n    void actualizarDesde(CuentaPorPagar c) {\n        this.ordenId = c.getOrdenId();\n        this.proveedorId = c.getProveedorId();\n        this.moneda = c.getMoneda();\n        this.monto = c.getMonto();\n        for (PagoProveedor p : c.getPagos()) {\n            boolean yaGuardado = pagos.stream().anyMatch(e -> e.getId().equals(p.getId()));\n            if (!yaGuardado) {\n                pagos.add(new PagoProveedorEntity(p.getId(), this, p.getMonto(), p.getFechaPago(), p.getReferencia()));\n            }\n        }\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id de la orden. */\n    public UUID getOrdenId() { return ordenId; }\n    /** Devuelve el id del proveedor. */\n    public UUID getProveedorId() { return proveedorId; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve el monto. */\n    public BigDecimal getMonto() { return monto; }\n    /** Devuelve los pagos de la cuenta. */\n    public List<PagoProveedorEntity> getPagos() { return pagos; }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/CuentaPorPagarJpaRepository.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de cuentas por pagar con Spring Data JPA. */\npublic interface CuentaPorPagarJpaRepository extends JpaRepository<CuentaPorPagarEntity, UUID> {\n\n    Optional<CuentaPorPagarEntity> findByOrdenId(UUID ordenId);\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/CuentaPorPagarRepositorioJpa.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagar;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagarRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoProveedor;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoResumen;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.PageRequest;\nimport org.springframework.stereotype.Component;\n\n/** Adaptador que implementa el puerto de dominio con JPA. */\n@Component\nclass CuentaPorPagarRepositorioJpa implements CuentaPorPagarRepositorio {\n\n    private final CuentaPorPagarJpaRepository jpa;\n    private final PagoProveedorJpaRepository pagos;\n\n    CuentaPorPagarRepositorioJpa(CuentaPorPagarJpaRepository jpa, PagoProveedorJpaRepository pagos) {\n        this.jpa = jpa;\n        this.pagos = pagos;\n    }\n\n    /** Devuelve los pagos más recientes con su cuenta, con límite. */\n    @Override\n    public List<PagoResumen> listarPagosRecientes(int limite) {\n        return pagos.findAllByOrderByFechaPagoDescCreadoUtcDesc(PageRequest.of(0, limite)).stream()\n                .map(p -> new PagoResumen(p.getId(), p.getCuenta().getId(), p.getMonto(), p.getFechaPago(),\n                        p.getReferencia()))\n                .toList();\n    }\n\n    /** Guarda una cuenta con sus pagos y devuelve la guardada. */\n    @Override\n    public CuentaPorPagar guardar(CuentaPorPagar cuenta) {\n        CuentaPorPagarEntity entidad = jpa.findById(cuenta.getId())\n                .orElseGet(() -> new CuentaPorPagarEntity(cuenta.getId()));\n        entidad.actualizarDesde(cuenta);\n        return aDominio(jpa.save(entidad));\n    }\n\n    /** Busca una cuenta por id. */\n    @Override\n    public Optional<CuentaPorPagar> buscarPorId(UUID id) {\n        return jpa.findById(id).map(this::aDominio);\n    }\n\n    /** Busca la cuenta de una orden de compra. */\n    @Override\n    public Optional<CuentaPorPagar> buscarPorOrdenId(UUID ordenId) {\n        return jpa.findByOrdenId(ordenId).map(this::aDominio);\n    }\n\n    /** Convierte la fila en la cuenta del dominio. */\n    private CuentaPorPagar aDominio(CuentaPorPagarEntity e) {\n        List<PagoProveedor> pagos = e.getPagos().stream()\n                .map(p -> new PagoProveedor(p.getId(), p.getMonto(), p.getFechaPago(), p.getReferencia()))\n                .toList();\n        return CuentaPorPagar.reconstruir(e.getId(), e.getOrdenId(), e.getProveedorId(), e.getMoneda(),\n                e.getMonto(), pagos);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/PagoEntity.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.ManyToOne;\nimport jakarta.persistence.PrePersist;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Mapeo JPA de un pago aplicado a un comprobante. */\n@Entity\n@Table(name = \"pagos\")\npublic class PagoEntity {\n\n    @Id\n    private UUID id;\n\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    @JoinColumn(name = \"comprobante_id\", nullable = false)\n    private ComprobanteEntity comprobante;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    private BigDecimal monto;\n\n    @Column(name = \"fecha_pago\", nullable = false)\n    private LocalDate fechaPago;\n\n    @Column(length = 100)\n    private String referencia;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected PagoEntity() {\n    }\n\n    PagoEntity(UUID id, ComprobanteEntity comprobante, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        this.id = id;\n        this.comprobante = comprobante;\n        this.monto = monto;\n        this.fechaPago = fechaPago;\n        this.referencia = referencia;\n    }\n\n    /** Se ejecuta antes de insertar la fila del pago. */\n    @PrePersist\n    void alPersistir() {\n        this.creadoUtc = Instant.now();\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el monto. */\n    public BigDecimal getMonto() { return monto; }\n    /** Devuelve la fecha del pago. */\n    public LocalDate getFechaPago() { return fechaPago; }\n    /** Devuelve la referencia. */\n    public String getReferencia() { return referencia; }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/PagoProveedorEntity.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.ManyToOne;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Mapeo JPA de un pago registrado contra una cuenta por pagar. */\n@Entity\n@Table(name = \"pagos_proveedor\")\npublic class PagoProveedorEntity {\n\n    @Id\n    private UUID id;\n\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    @JoinColumn(name = \"cuenta_id\", nullable = false)\n    private CuentaPorPagarEntity cuenta;\n\n    @Column(nullable = false, precision = 14, scale = 2)\n    private BigDecimal monto;\n\n    @Column(name = \"fecha_pago\", nullable = false)\n    private LocalDate fechaPago;\n\n    @Column(length = 100)\n    private String referencia;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected PagoProveedorEntity() {\n    }\n\n    PagoProveedorEntity(UUID id, CuentaPorPagarEntity cuenta, BigDecimal monto, LocalDate fechaPago, String referencia) {\n        this.id = id;\n        this.cuenta = cuenta;\n        this.monto = monto;\n        this.fechaPago = fechaPago;\n        this.referencia = referencia;\n        this.creadoUtc = Instant.now();\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el monto. */\n    public BigDecimal getMonto() { return monto; }\n    /** Devuelve la fecha del pago. */\n    public LocalDate getFechaPago() { return fechaPago; }\n    /** Devuelve la referencia. */\n    public String getReferencia() { return referencia; }\n\n    /** Devuelve la cuenta a la que pertenece el pago. */\n    public CuentaPorPagarEntity getCuenta() {\n        return cuenta;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/persistence/PagoProveedorJpaRepository.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de pagos a proveedores con Spring Data JPA. */\npublic interface PagoProveedorJpaRepository extends JpaRepository<PagoProveedorEntity, UUID> {\n\n    List<PagoProveedorEntity> findAllByOrderByFechaPagoDescCreadoUtcDesc(Pageable pageable);\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.facturacion_pagos.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.facturacion_pagos.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"facturacion-pagos-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n     * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n     * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.facturacion_pagos.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/facturacion_pagos/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.facturacion_pagos.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/api/ComprobanteControladorAutorizacionTest.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.FacturacionService;\nimport com.mx.josesaid.develop.facturacion_pagos.config.SeguridadConfig;\nimport com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de ComprobanteControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n */\n@WebMvcTest(ComprobanteControlador.class)\n@Import({SeguridadConfig.class, ComprobanteControladorAutorizacionTest.Configuracion.class})\nclass ComprobanteControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String CREAR = \"{\\\"ordenId\\\":\\\"\" + ID + \"\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"subtotal\\\":100}\";\n    private static final String CANCELAR = \"{\\\"motivo\\\":\\\"Error en el monto\\\"}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private FacturacionService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private MockHttpServletRequestBuilder lectura(String ruta, String rol) {\n        return peticion(get(ruta), rol);\n    }\n\n    private MockHttpServletRequestBuilder escritura(String ruta, String cuerpo, String rol) {\n        var base = post(ruta).contentType(MediaType.APPLICATION_JSON);\n        if (cuerpo != null) {\n            base = base.content(cuerpo);\n        }\n        return peticion(base, rol);\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void crearComprobante() throws Exception {\n        permitido(escritura(\"/v1/comprobantes\", CREAR, \"FINANZAS\"), \"POST comprobantes\", \"FINANZAS\");\n        denegado(escritura(\"/v1/comprobantes\", CREAR, \"VENTAS\"));\n    }\n\n    @Test\n    void buscarPorFolio() throws Exception {\n        String ruta = \"/v1/comprobantes?folio=A-1\";\n        permitido(lectura(ruta, \"FINANZAS\"), \"GET folio\", \"FINANZAS\");\n        permitido(lectura(ruta, \"VENTAS\"), \"GET folio\", \"VENTAS\");\n        denegado(lectura(ruta, \"LEGAL\"));\n    }\n\n    @Test\n    void listarPendientesCobro() throws Exception {\n        String ruta = \"/v1/comprobantes/pendientes-cobro\";\n        permitido(lectura(ruta, \"FINANZAS\"), \"GET pendientes\", \"FINANZAS\");\n        permitido(lectura(ruta, \"VENTAS\"), \"GET pendientes\", \"VENTAS\");\n        denegado(lectura(ruta, \"LEGAL\"));\n    }\n\n    @Test\n    void obtenerComprobante() throws Exception {\n        String ruta = \"/v1/comprobantes/\" + ID;\n        permitido(lectura(ruta, \"FINANZAS\"), \"GET comprobante\", \"FINANZAS\");\n        permitido(lectura(ruta, \"VENTAS\"), \"GET comprobante\", \"VENTAS\");\n        denegado(lectura(ruta, \"LEGAL\"));\n    }\n\n    @Test\n    void emitirComprobante() throws Exception {\n        String ruta = \"/v1/comprobantes/\" + ID + \"/emision\";\n        permitido(escritura(ruta, null, \"FINANZAS\"), \"POST emision\", \"FINANZAS\");\n        denegado(escritura(ruta, null, \"VENTAS\"));\n    }\n\n    @Test\n    void cancelarComprobante() throws Exception {\n        String ruta = \"/v1/comprobantes/\" + ID + \"/cancelacion\";\n        permitido(escritura(ruta, CANCELAR, \"FINANZAS\"), \"POST cancelacion\", \"FINANZAS\");\n        denegado(escritura(ruta, CANCELAR, \"VENTAS\"));\n    }\n\n    @Test\n    void registrarPagoSobreComprobante() throws Exception {\n        String ruta = \"/v1/comprobantes/\" + ID + \"/pagos\";\n        String pago = \"{\\\"monto\\\":100,\\\"fechaPago\\\":\\\"2026-11-05\\\",\\\"referencia\\\":\\\"REF-1\\\"}\";\n        permitido(escritura(ruta, pago, \"FINANZAS\"), \"POST pagos\", \"FINANZAS\");\n        denegado(escritura(ruta, pago, \"VENTAS\"));\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(lectura(\"/v1/comprobantes/\" + ID, \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/api/ComprobanteControladorValidacionTest.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.FacturacionService;\nimport com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia.Idempotencia;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(ComprobanteControlador.class)\n@Import(ComprobanteControladorValidacionTest.Configuracion.class)\nclass ComprobanteControladorValidacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private FacturacionService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    @Test\n    void parametroDemasiadoLargoDa400() throws Exception {\n        mvc.perform(get(\"/v1/comprobantes\").param(\"folio\", \"A\".repeat(51))\n                        .with(jwt().jwt(j -> j.subject(SUJETO))\n                                .authorities(new SimpleGrantedAuthority(\"ROLE_FINANZAS\"))))\n                .andExpect(status().isBadRequest());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/api/CuentasPorPagarControladorAutorizacionTest.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.facturacion_pagos.application.CuentasPorPagarService;\nimport com.mx.josesaid.develop.facturacion_pagos.config.SeguridadConfig;\nimport com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de CuentasPorPagarControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n */\n@WebMvcTest(CuentasPorPagarControlador.class)\n@Import({SeguridadConfig.class, CuentasPorPagarControladorAutorizacionTest.Configuracion.class})\nclass CuentasPorPagarControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String PAGO = \"{\\\"monto\\\":100,\\\"fechaPago\\\":\\\"2026-11-05\\\",\\\"referencia\\\":\\\"REF-1\\\"}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private CuentasPorPagarService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void listarPagos() throws Exception {\n        String ruta = \"/v1/cuentas-por-pagar/pagos\";\n        permitido(peticion(get(ruta), \"FINANZAS\"), \"GET pagos\", \"FINANZAS\");\n        denegado(peticion(get(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void obtenerCuenta() throws Exception {\n        String ruta = \"/v1/cuentas-por-pagar/\" + ID;\n        permitido(peticion(get(ruta), \"FINANZAS\"), \"GET cuenta\", \"FINANZAS\");\n        denegado(peticion(get(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void registrarPagoProveedor() throws Exception {\n        String ruta = \"/v1/cuentas-por-pagar/\" + ID + \"/pagos\";\n        permitido(peticion(post(ruta).contentType(MediaType.APPLICATION_JSON).content(PAGO), \"FINANZAS\"),\n                \"POST pagos\", \"FINANZAS\");\n        denegado(peticion(post(ruta).contentType(MediaType.APPLICATION_JSON).content(PAGO), \"VENTAS\"));\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(peticion(get(\"/v1/cuentas-por-pagar/\" + ID), \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/api/FacturacionPagosIT.java": "package com.mx.josesaid.develop.facturacion_pagos.api;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.TasaIva;\n\nimport java.time.ZoneId;\n\nimport java.time.LocalDate;\n\nimport java.math.RoundingMode;\n\nimport java.math.BigDecimal;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/**\n * Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; se ejecuta con 'mvn verify'.\n * La autenticación se simula con el post-procesador jwt() de spring-security-test.\n */\n@SpringBootTest(properties = \"facturacion.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@AutoConfigureMockMvc\n@Testcontainers\nclass FacturacionPagosIT {\n\n    private static final String ORDEN = \"00000000-0000-0000-0000-000000000001\";\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Test\n    void buscaComprobantePorFolioExacto() throws Exception {\n        MvcResult creado = mvc.perform(post(\"/v1/comprobantes\").with(finanzas())\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"ordenId\\\":\\\"\" + ORDEN + \"\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"subtotal\\\":1000}\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        String id = JsonPath.read(creado.getResponse().getContentAsString(), \"$.id\");\n        MvcResult emitido = mvc.perform(post(\"/v1/comprobantes/\" + id + \"/emision\").with(finanzas()))\n                .andExpect(status().isOk())\n                .andReturn();\n        String folio = JsonPath.read(emitido.getResponse().getContentAsString(), \"$.folio\");\n\n        mvc.perform(get(\"/v1/comprobantes\").param(\"folio\", folio).with(finanzas()))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.id\").value(id));\n\n        mvc.perform(get(\"/v1/comprobantes\").param(\"folio\", \"NO-EXISTE\").with(finanzas()))\n                .andExpect(status().isNotFound());\n    }\n\n    @Test\n    void flujoDeComprobanteConRolesYReglas() throws Exception {\n        // Sin token: no autenticado\n        mvc.perform(get(\"/v1/comprobantes/00000000-0000-0000-0000-000000000000\"))\n                .andExpect(status().isUnauthorized());\n\n        // VENTAS no puede crear comprobantes\n        mvc.perform(post(\"/v1/comprobantes\").with(jwt().authorities(new SimpleGrantedAuthority(\"ROLE_VENTAS\")))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"ordenId\\\":\\\"\" + ORDEN + \"\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"subtotal\\\":1000}\"))\n                .andExpect(status().isForbidden());\n\n        // FINANZAS crea, emite y cobra\n        MvcResult creado = mvc.perform(post(\"/v1/comprobantes\").with(finanzas())\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"ordenId\\\":\\\"\" + ORDEN + \"\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"subtotal\\\":1000}\"))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.total\").value(totalEsperadoMxn(1000)))\n                .andReturn();\n        String id = JsonPath.read(creado.getResponse().getContentAsString(), \"$.id\");\n\n        mvc.perform(post(\"/v1/comprobantes/\" + id + \"/emision\").with(finanzas()))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"EMITIDO\"))\n                .andExpect(jsonPath(\"$.folio\").isNotEmpty());\n\n        mvc.perform(post(\"/v1/comprobantes/\" + id + \"/pagos\").with(finanzas())\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"monto\\\":2000}\"))\n                .andExpect(status().isUnprocessableEntity());\n\n        mvc.perform(post(\"/v1/comprobantes/\" + id + \"/pagos\").with(finanzas())\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"monto\\\":\" + totalEsperadoMxn(1000) + \",\\\"referencia\\\":\\\"SPEI-1\\\"}\"))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.estatusCobro\").value(\"PAGADO\"))\n                .andExpect(jsonPath(\"$.pagos.length()\").value(1));\n\n        mvc.perform(get(\"/v1/comprobantes/\" + id).with(jwt().authorities(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.saldo\").value(0));\n    }\n\n    private static double totalEsperadoMxn(double subtotal) {\n        BigDecimal base = BigDecimal.valueOf(subtotal);\n        BigDecimal tasa = TasaIva.paraFecha(LocalDate.now(ZoneId.of(\"America/Mexico_City\")));\n        return base.add(base.multiply(tasa)).setScale(2, RoundingMode.HALF_EVEN).doubleValue();\n    }\n\n    private static org.springframework.test.web.servlet.request.RequestPostProcessor finanzas() {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_FINANZAS\"));\n    }\n\n    @Test\n    void mismaIdempotencyKeyNoDuplicaElPago() throws Exception {\n        MvcResult creado = mvc.perform(post(\"/v1/comprobantes\").with(finanzas())\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"ordenId\\\":\\\"00000000-0000-0000-0000-000000000003\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"subtotal\\\":500}\"))\n                .andExpect(status().isCreated()).andReturn();\n        String id = JsonPath.read(creado.getResponse().getContentAsString(), \"$.id\");\n        mvc.perform(post(\"/v1/comprobantes/\" + id + \"/emision\").with(finanzas())).andExpect(status().isOk());\n\n        String cuerpo = \"{\\\"monto\\\":500,\\\"referencia\\\":\\\"SPEI-IDEM\\\"}\";\n        String clave = \"prueba-\" + java.util.UUID.randomUUID();\n        MvcResult primero = mvc.perform(post(\"/v1/comprobantes/\" + id + \"/pagos\").with(finanzas())\n                        .header(\"Idempotency-Key\", clave).contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        MvcResult reintento = mvc.perform(post(\"/v1/comprobantes/\" + id + \"/pagos\").with(finanzas())\n                        .header(\"Idempotency-Key\", clave).contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        assertEquals(primero.getResponse().getContentAsString(), reintento.getResponse().getContentAsString());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/application/CuentasPorPagarListadoPagosTest.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagarRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.PagoResumen;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass CuentasPorPagarListadoPagosTest {\n\n    @Test\n    void listaHastaQuinceArriba() {\n        CuentaPorPagarRepositorio cuentas = mock(CuentaPorPagarRepositorio.class);\n        PagoResumen pago = new PagoResumen(UUID.randomUUID(), UUID.randomUUID(), new BigDecimal(\"150.00\"),\n                LocalDate.of(2026, 11, 4), \"SPEI-1\");\n        when(cuentas.listarPagosRecientes(eq(15))).thenReturn(List.of(pago));\n        CuentasPorPagarService servicio = new CuentasPorPagarService(cuentas, mock(PublicadorEventos.class),\n                Clock.systemUTC());\n\n        List<PagoResumen> resultado = servicio.listarPagosRecientes();\n\n        verify(cuentas).listarPagosRecientes(15);\n        assertThat(resultado).containsExactly(pago);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/application/CuentasPorPagarServiceTest.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.times;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagar;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.CuentaPorPagarRepositorio;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.ZoneOffset;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass CuentasPorPagarServiceTest {\n\n    private final CuentaPorPagarRepositorio repo = mock(CuentaPorPagarRepositorio.class);\n    private final PublicadorEventos eventos = mock(PublicadorEventos.class);\n    private final Clock reloj = Clock.fixed(Instant.parse(\"2026-11-05T18:00:00Z\"), ZoneOffset.UTC);\n    private final CuentasPorPagarService servicio = new CuentasPorPagarService(repo, eventos, reloj);\n\n    @Test\n    void registrarCuentaNoDuplicaLaCuentaDeUnaOrden() {\n        UUID orden = UUID.randomUUID();\n        when(repo.buscarPorOrdenId(orden)).thenReturn(Optional.empty());\n        servicio.registrarCuenta(orden, UUID.randomUUID(), \"MXN\", new BigDecimal(\"500\"));\n        verify(repo, times(1)).guardar(any(CuentaPorPagar.class));\n\n        CuentaPorPagar existente = CuentaPorPagar.crear(orden, UUID.randomUUID(), \"MXN\", BigDecimal.TEN);\n        when(repo.buscarPorOrdenId(orden)).thenReturn(Optional.of(existente));\n        servicio.registrarCuenta(orden, UUID.randomUUID(), \"MXN\", new BigDecimal(\"500\"));\n        verify(repo, times(1)).guardar(any(CuentaPorPagar.class));\n    }\n\n    @Test\n    void registrarPagoPublicaEventoConSaldoYFechaDelReloj() {\n        CuentaPorPagar cuenta = CuentaPorPagar.crear(UUID.randomUUID(), UUID.randomUUID(), \"MXN\", new BigDecimal(\"1000\"));\n        when(repo.buscarPorId(cuenta.getId())).thenReturn(Optional.of(cuenta));\n        when(repo.guardar(any(CuentaPorPagar.class))).thenAnswer(inv -> inv.getArgument(0));\n\n        CuentaPorPagar guardada = servicio.registrarPago(cuenta.getId(), new BigDecimal(\"250\"), null, \"SPEI-7\");\n\n        assertThat(guardada.saldo()).isEqualByComparingTo(\"750.00\");\n        assertThat(guardada.getPagos().get(0).getFechaPago()).isEqualTo(LocalDate.of(2026, 11, 5));\n        verify(eventos).publicar(any(EventoDominio.class));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/application/FacturacionListadoPendientesTest.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobantePendienteCobro;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobanteRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusCobro;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass FacturacionListadoPendientesTest {\n\n    @Test\n    void listaHastaQuinceComprobantesPendientes() {\n        ComprobanteRepositorio repositorio = mock(ComprobanteRepositorio.class);\n        ComprobantePendienteCobro pendiente = new ComprobantePendienteCobro(UUID.randomUUID(), \"F-1\", \"MXN\",\n                new BigDecimal(\"1160.00\"), new BigDecimal(\"1160.00\"), EstatusCobro.PENDIENTE);\n        when(repositorio.listarPendientesDeCobro(eq(15))).thenReturn(List.of(pendiente));\n        FacturacionService servicio = new FacturacionService(repositorio, mock(PublicadorEventos.class),\n                Clock.systemUTC());\n\n        List<ComprobantePendienteCobro> resultado = servicio.listarPendientesDeCobro();\n\n        verify(repositorio).listarPendientesDeCobro(15);\n        assertThat(resultado).containsExactly(pendiente);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/application/FacturacionServiceTest.java": "package com.mx.josesaid.develop.facturacion_pagos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport com.mx.josesaid.develop.facturacion_pagos.domain.Comprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobanteRepositorio;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.ComprobantePendienteCobro;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.EstatusComprobante;\nimport com.mx.josesaid.develop.facturacion_pagos.domain.RecursoNoEncontradoException;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass FacturacionServiceTest {\n\n    private final Map<UUID, Comprobante> almacen = new HashMap<>();\n    private final List<EventoDominio> eventos = new ArrayList<>();\n    private FacturacionService servicio;\n\n    @BeforeEach\n    void preparar() {\n        ComprobanteRepositorio repo = new ComprobanteRepositorio() {\n            @Override\n            public Comprobante guardar(Comprobante c) {\n                almacen.put(c.getId(), c);\n                return c;\n            }\n\n            @Override\n            public Optional<Comprobante> buscarPorId(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n\n            @Override\n            public Optional<Comprobante> buscarPorFolio(String folio) {\n                return almacen.values().stream().filter(c -> folio.equals(c.getFolio())).findFirst();\n            }\n\n            @Override\n            public List<ComprobantePendienteCobro> listarPendientesDeCobro(int limite) {\n                return List.of();\n            }\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-01-15T10:00:00Z\"), ZoneOffset.UTC);\n        servicio = new FacturacionService(repo, eventos::add, reloj);\n    }\n\n    @Test\n    void flujoCompletoPublicaEventos() {\n        Comprobante c = servicio.crearBorrador(UUID.randomUUID(), \"MXN\", new BigDecimal(\"100\"));\n        servicio.emitir(c.getId());\n        servicio.registrarPago(c.getId(), new BigDecimal(\"50\"), null, \"REF-1\");\n        servicio.cancelar(c.getId(), \"Duplicado\");\n\n        assertThat(eventos).extracting(EventoDominio::tipo).containsExactly(\n                FacturacionService.EVENTO_COMPROBANTE_EMITIDO,\n                FacturacionService.EVENTO_PAGO_REGISTRADO,\n                FacturacionService.EVENTO_COMPROBANTE_CANCELADO);\n        assertThat(servicio.obtener(c.getId()).getEstatus()).isEqualTo(EstatusComprobante.CANCELADO);\n    }\n\n    @Test\n    void pagoSinFechaUsaLaFechaDelReloj() {\n        Comprobante c = servicio.crearBorrador(UUID.randomUUID(), \"USD\", new BigDecimal(\"10\"));\n        servicio.emitir(c.getId());\n        Comprobante actualizado = servicio.registrarPago(c.getId(), BigDecimal.ONE, null, null);\n        assertThat(actualizado.getPagos().get(0).getFechaPago()).isEqualTo(LocalDate.of(2026, 1, 15));\n    }\n\n    @Test\n    void comprobanteInexistenteEsNoEncontrado() {\n        assertThatThrownBy(() -> servicio.obtener(UUID.randomUUID()))\n                .isInstanceOf(RecursoNoEncontradoException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/config/RelojConfigTest.java": "package com.mx.josesaid.develop.facturacion_pagos.config;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.time.ZoneId;\nimport org.junit.jupiter.api.Test;\n\nclass RelojConfigTest {\n\n    @Test\n    void relojUsaLaZonaDeOperacion() {\n        assertEquals(ZoneId.of(\"America/Mexico_City\"), new RelojConfig().reloj().getZone());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/domain/ComprobanteTest.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass ComprobanteTest {\n\n    private static Comprobante borrador() {\n        return Comprobante.crearBorrador(UUID.randomUUID(), \"MXN\", new BigDecimal(\"1000\"), LocalDate.of(2026, 1, 15));\n    }\n\n    @Test\n    void calculaIvaYTotalConRedondeoBancario() {\n        Comprobante c = borrador();\n        assertThat(c.getIva()).isEqualByComparingTo(\"160.00\");\n        assertThat(c.getTotal()).isEqualByComparingTo(\"1160.00\");\n        assertThat(c.getEstatus()).isEqualTo(EstatusComprobante.BORRADOR);\n        assertThat(c.getFolio()).isNull();\n    }\n\n    @Test\n    void rechazaMonedaNoPermitida() {\n        assertThatThrownBy(() -> Comprobante.crearBorrador(UUID.randomUUID(), \"EUR\", BigDecimal.TEN, LocalDate.of(2026, 1, 15)))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void emitirAsignaFolioYNoSePuedeRepetir() {\n        Comprobante c = borrador();\n        c.emitir();\n        assertThat(c.getEstatus()).isEqualTo(EstatusComprobante.EMITIDO);\n        assertThat(c.getFolio()).startsWith(\"FAC-\");\n        assertThatThrownBy(c::emitir).isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void cancelarExigeMotivoYSoloAplicaAEmitidos() {\n        Comprobante c = borrador();\n        assertThatThrownBy(() -> c.cancelar(\"x\")).isInstanceOf(ReglaDeNegocioException.class);\n        c.emitir();\n        assertThatThrownBy(() -> c.cancelar(\"  \")).isInstanceOf(ReglaDeNegocioException.class);\n        c.cancelar(\"Error en importe\");\n        assertThat(c.getEstatus()).isEqualTo(EstatusComprobante.CANCELADO);\n        assertThat(c.getMotivoCancelacion()).isEqualTo(\"Error en importe\");\n    }\n\n    @Test\n    void pagosSoloEnEmitidosYNoExcedenElSaldo() {\n        Comprobante c = borrador();\n        assertThatThrownBy(() -> c.registrarPago(BigDecimal.ONE, LocalDate.now(), null))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        c.emitir();\n        c.registrarPago(new BigDecimal(\"500\"), LocalDate.now(), \"SPEI-1\");\n        assertThat(c.estatusCobro()).isEqualTo(EstatusCobro.PARCIAL);\n        assertThat(c.saldo()).isEqualByComparingTo(\"660.00\");\n        assertThatThrownBy(() -> c.registrarPago(new BigDecimal(\"661\"), LocalDate.now(), null))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"excede\");\n        c.registrarPago(new BigDecimal(\"660\"), LocalDate.now(), null);\n        assertThat(c.estatusCobro()).isEqualTo(EstatusCobro.PAGADO);\n        assertThat(c.getPagos()).hasSize(2);\n    }\n\n    @Test\n    void sinPagosElEstatusDeCobroEsPendiente() {\n        Comprobante c = borrador();\n        c.emitir();\n        assertThat(c.estatusCobro()).isEqualTo(EstatusCobro.PENDIENTE);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/domain/CuentaPorPagarTest.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass CuentaPorPagarTest {\n\n    private static final LocalDate HOY = LocalDate.of(2026, 11, 5);\n\n    private static CuentaPorPagar cuenta(String total) {\n        return CuentaPorPagar.crear(UUID.randomUUID(), UUID.randomUUID(), \"MXN\", new BigDecimal(total));\n    }\n\n    @Test\n    void recienCreadaEstaPendienteConSaldoTotal() {\n        CuentaPorPagar c = cuenta(\"1000\");\n        assertThat(c.estatus()).isEqualTo(EstatusCuentaPorPagar.PENDIENTE);\n        assertThat(c.saldo()).isEqualByComparingTo(\"1000.00\");\n    }\n\n    @Test\n    void pagoParcialDejaLaCuentaParcial() {\n        CuentaPorPagar c = cuenta(\"1000\");\n        c.registrarPago(new BigDecimal(\"400\"), HOY, \"SPEI-1\");\n        assertThat(c.estatus()).isEqualTo(EstatusCuentaPorPagar.PARCIAL);\n        assertThat(c.saldo()).isEqualByComparingTo(\"600.00\");\n    }\n\n    @Test\n    void pagoTotalSaldaLaCuenta() {\n        CuentaPorPagar c = cuenta(\"1000\");\n        c.registrarPago(new BigDecimal(\"1000\"), HOY, null);\n        assertThat(c.estatus()).isEqualTo(EstatusCuentaPorPagar.PAGADA);\n        assertThat(c.saldo()).isEqualByComparingTo(\"0.00\");\n    }\n\n    @Test\n    void pagoQueExcedeElSaldoSeRechaza() {\n        CuentaPorPagar c = cuenta(\"1000\");\n        assertThatThrownBy(() -> c.registrarPago(new BigDecimal(\"1000.01\"), HOY, null))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"excede el saldo\");\n    }\n\n    @Test\n    void montoNoPositivoOFechaFaltanteSeRechazan() {\n        CuentaPorPagar c = cuenta(\"1000\");\n        assertThatThrownBy(() -> c.registrarPago(BigDecimal.ZERO, HOY, null))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        assertThatThrownBy(() -> c.registrarPago(new BigDecimal(\"0.001\"), HOY, null))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        assertThatThrownBy(() -> c.registrarPago(new BigDecimal(\"10\"), null, null))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void monedaNoPermitidaSeRechaza() {\n        assertThatThrownBy(() -> CuentaPorPagar.crear(UUID.randomUUID(), UUID.randomUUID(), \"EUR\", BigDecimal.TEN))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/domain/TasaIvaTest.java": "package com.mx.josesaid.develop.facturacion_pagos.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\n\nclass TasaIvaTest {\n\n    @Test\n    void antesDelPrimeroDeNoviembreEs16() {\n        assertThat(TasaIva.paraFecha(LocalDate.of(2026, 10, 31))).isEqualByComparingTo(\"0.16\");\n    }\n\n    @Test\n    void desdeElPrimeroDeNoviembreEs8() {\n        assertThat(TasaIva.paraFecha(LocalDate.of(2026, 11, 1))).isEqualByComparingTo(\"0.08\");\n    }\n\n    @Test\n    void comprobanteUsaLaTasaDeSuFecha() {\n        Comprobante c = Comprobante.crearBorrador(UUID.randomUUID(), \"MXN\", new BigDecimal(\"1000\"),\n                LocalDate.of(2026, 11, 5));\n        assertThat(c.getTasaIva()).isEqualByComparingTo(\"0.08\");\n        assertThat(c.getIva()).isEqualByComparingTo(\"80.00\");\n        assertThat(c.getTotal()).isEqualByComparingTo(\"1080.00\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/idempotencia/RegistroIdempotenciaIT.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.idempotencia;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport org.flywaydb.core.Flyway;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.datasource.DriverManagerDataSource;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Reserva de Idempotency-Key contra PostgreSQL real (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@Testcontainers\nclass RegistroIdempotenciaIT {\n\n    @Container\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    private static final Instant T0 = Instant.parse(\"2026-11-05T12:00:00Z\");\n\n    private JdbcTemplate jdbc;\n\n    @BeforeEach\n    void migrarBaseLimpia() {\n        DriverManagerDataSource ds = new DriverManagerDataSource(\n                postgres.getJdbcUrl(), postgres.getUsername(), postgres.getPassword());\n        Flyway flyway = Flyway.configure().dataSource(ds).cleanDisabled(false).load();\n        flyway.clean();\n        flyway.migrate();\n        jdbc = new JdbcTemplate(ds);\n    }\n\n    private RegistroIdempotencia registroEn(Instant instante) {\n        return new RegistroIdempotencia(jdbc, Clock.fixed(instante, ZoneOffset.UTC));\n    }\n\n    @Test\n    void reservaFrescaNoSeRetoma() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertFalse(registroEn(T0.plusSeconds(60)).reservar(\"k1\", \"h1\"));\n    }\n\n    @Test\n    void reservaSinCompletarSeRetomaTrasLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h2\"));\n        assertEquals(\"h2\", registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().huella());\n        assertFalse(registroEn(T0.plusSeconds(200)).reservar(\"k1\", \"h2\"));\n    }\n\n    @Test\n    void respuestaCompletadaNoSeRetomaAunquePaseLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        registroEn(T0).completar(\"k1\", 201, \"{}\");\n        assertFalse(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().completada());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/facturacion_pagos/infrastructure/indicadores/PublicadorIndicadoresCobranzaIT.java": "package com.mx.josesaid.develop.facturacion_pagos.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.math.BigDecimal;\nimport java.time.Duration;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"facturacion.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@Testcontainers\nclass PublicadorIndicadoresCobranzaIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresCobranza publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void cobradoDelMesSumaPagosMxnDeComprobantesEmitidos() {\n        String periodo = YearMonth.now(ZONA).toString();\n        UUID emitido = comprobante(\"EMITIDO\", \"MXN\");\n        pago(emitido, \"50.00\");\n        pago(emitido, \"30.00\");\n        pago(comprobante(\"BORRADOR\", \"MXN\"), \"100.00\");  // excluido: comprobante en borrador\n        pago(comprobante(\"EMITIDO\", \"USD\"), \"40.00\");    // excluido: no es MXN\n\n        publicador.publicarPeriodo(periodo);\n\n        String clave = PublicadorIndicadoresCobranza.AREA + \"|\" + PublicadorIndicadoresCobranza.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"FINANZAS_CONTABILIDAD\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(80.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private UUID comprobante(String estatus, String moneda) {\n        UUID id = UUID.randomUUID();\n        jdbc.update(\"\"\"\n                INSERT INTO comprobantes (id, orden_id, moneda, subtotal, iva, total, tasa_iva, estatus,\n                                          version, creado_utc, actualizado_utc)\n                VALUES (?, ?, ?, 100.00, 16.00, 116.00, 0.16, ?, 0, now(), now())\n                \"\"\", id, UUID.randomUUID(), moneda, estatus);\n        return id;\n    }\n\n    private void pago(UUID comprobanteId, String monto) {\n        jdbc.update(\"\"\"\n                INSERT INTO pagos (id, comprobante_id, monto, fecha_pago, creado_utc)\n                VALUES (?, ?, ?, ?, now())\n                \"\"\", UUID.randomUUID(), comprobanteId, new BigDecimal(monto),\n                java.sql.Date.valueOf(LocalDate.now(ZONA)));\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n"};
